/*
 Добавьте обработку события onkeydown для объекта document. Затем напишите функцию-обработчик,
 которая при нажатии Ctrl+Shift+H выведет alert с текстом Вы нажали Ctrl+Shift+H.
*/

document.onkeydown = function (event) {
  if (event.ctrlKey && event.shiftKey && event.key.toLowerCase() === 'h') {
    alert('Вы нажали Ctrl+Shift+H');
  }
};
